import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BU31gs4v.js";const p=JSON.parse('{"title":"第 10 章 教模型管理记忆：读一份系统提示","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/10-teaching-memory.md","filePath":"chapters/10-teaching-memory.md","lastUpdated":1791479463000}'),d={name:"chapters/10-teaching-memory.md"};function s(r,e,i,c,l,m){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第-10-章-教模型管理记忆-读一份系统提示" tabindex="-1">第 10 章 教模型管理记忆：读一份系统提示 <a class="header-anchor" href="#第-10-章-教模型管理记忆-读一份系统提示" aria-label="Permalink to &quot;第 10 章 教模型管理记忆：读一份系统提示&quot;">​</a></h1><blockquote><p>本章目标：逐节读 letta-code 给 MemFS agent 的系统提示，看清哪些规则只是“说给模型听”，哪些被代码强制执行；理解为什么记忆系统的一半是提示词工程。前置：第 4–9 章。对应代码：mini-letta <code>v0.2</code> 起的 <code>DEFAULT_SYSTEM_PROMPT</code>（<code>src/store/agent-store.ts</code>）。</p></blockquote><h2 id="_10-1-两份提示词" tabindex="-1">10.1 两份提示词 <a class="header-anchor" href="#_10-1-两份提示词" aria-label="Permalink to &quot;10.1 两份提示词&quot;">​</a></h2><p>letta-code 为 MemFS agent 准备了两份完整的系统提示（<code>src/agent/prompts/README.md</code>）：</p><table tabindex="0"><thead><tr><th>文件</th><th>给谁</th><th>怎么选出来的</th></tr></thead><tbody><tr><td><code>letta_root_memfs.md</code>（约 3500 词）</td><td>Letta Cloud 上的 agent</td><td><code>root-memfs</code> 模式</td></tr><tr><td><code>letta_local_memfs.md</code>（约 3300 词）</td><td>本地后端的 agent</td><td><code>local-memfs</code> 模式</td></tr></tbody></table><p>选择逻辑在 <code>src/agent/personality.ts:112-121</code>：<code>environment === &quot;local&quot;</code> → <code>local-memfs</code>；Cloud 上是 Letta Cloud 才用 <code>root-memfs</code>，自托管服务器用旧的 <code>memfs</code>。<code>buildSystemPrompt()</code>（<code>src/agent/prompt-assets.ts</code>）按模式取对应内容。</p><p>两份的差别值得一看（<code>diff letta_local_memfs.md letta_root_memfs.md</code> 的前几处）：</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-## Memory blocks &amp; external memory (learning)</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+## Memory files &amp; external memory (learning)</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-### Memory blocks (in-context memory)</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+### Core memory (in-context memory)</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-Memory blocks are editable segments of the system prompt. Each block has a name and description ...</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+Root Markdown files are editable segments of the system prompt. Root `MEMORY.md` is a frontmatter-free</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+overview and index. Every other root Markdown file is core memory with exactly `name` and `description`</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+frontmatter. ...</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-- *References as synapses.* Use [[path]] links from memory blocks ...</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+- *References as synapses.* Use ordinary relative Markdown links from `MEMORY.md` files ...</span></span></code></pre></div><p>也就是说，在 <code>70ead335</code> 上，本地 agent 的<strong>文件</strong>是 v2 根布局（第 2 章），hook 也按 v2 规则校验，但它的<strong>提示词</strong>仍用“memory blocks”的词汇、推荐 <code>[[path]]</code> 式链接，没有讲根 <code>MEMORY.md</code> 和“恰好 name + description”的规则。这些规则模型只能从 hook 的报错里学到。这是一个提示词落后于实现的例子，读源码时值得留意。本章以下引用都来自更新的 <code>letta_root_memfs.md</code>。</p><h2 id="_10-2-逐节读" tabindex="-1">10.2 逐节读 <a class="header-anchor" href="#_10-2-逐节读" aria-label="Permalink to &quot;10.2 逐节读&quot;">​</a></h2><h3 id="身份宣言-第-1–3-行" tabindex="-1">身份宣言（第 1–3 行） <a class="header-anchor" href="#身份宣言-第-1–3-行" aria-label="Permalink to &quot;身份宣言（第 1–3 行）&quot;">​</a></h3><blockquote><p>You are a Letta Code agent — a new generation of agent built for experiential learning… the model is the engine; <em>you</em> are the tokens.</p></blockquote><p>这段看似“文案”，实际上在给后面所有规则提供<strong>动机</strong>：如果 agent 把自己当成会话结束就消失的工具，它没有理由花 token 去维护记忆。提示词在 “Learning from mistakes”（<code>:79</code>）一节把这个经济学讲透了：无状态的 agent 反思错误是浪费，有状态的 agent 不反思才是浪费。</p><h3 id="context-architecture-5-起" tabindex="-1">Context Architecture（<code>:5</code> 起） <a class="header-anchor" href="#context-architecture-5-起" aria-label="Permalink to &quot;Context Architecture（`:5` 起）&quot;">​</a></h3><p>第 1 章的四类记忆就出自这里。值得注意的是它对 recall 的定位：“cannot be mutated”——经历是只读的，学习只能写进记忆文件。</p><h3 id="core-memory-26-起" tabindex="-1">Core memory（<code>:26</code> 起） <a class="header-anchor" href="#core-memory-26-起" aria-label="Permalink to &quot;Core memory（`:26` 起）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>只是提示？</th><th>代码强制在哪</th></tr></thead><tbody><tr><td>根 <code>MEMORY.md</code> 无 frontmatter，其他根文件恰好 <code>name</code>+<code>description</code></td><td>否</td><td>hook：<code>validateMemoryFileFrontmatter</code>（第 7 章）</td></tr><tr><td>子目录必须有 <code>MEMORY.md</code> 才算记忆</td><td>否</td><td>hook：树约束的索引链检查</td></tr><tr><td><code>skills/</code> 与记忆索引分开</td><td>否</td><td>hook：拒绝扁平技能文件</td></tr><tr><td>References as synapses：用相对链接把记忆连起来</td><td><strong>是</strong></td><td>无（链接断了没人报错——练习 2）</td></tr><tr><td>Never store secrets</td><td><strong>是</strong></td><td>无（letta-code 的 hook 不扫描密钥）</td></tr><tr><td>Keep core memory lean</td><td>部分</td><td><code>maxCoreMemoryCharacters</code>（默认 65 536 字符）；<code>/doctor</code> 提示过大</td></tr></tbody></table><p>“Keep core memory lean”的那句很重要（<code>:35</code>）：“Do <em>NOT</em> write memories that are easily derivable from searching past conversations (recall) or re-reading files.” 记忆不是备份，是<strong>提炼</strong>。</p><h3 id="syncing-memory-53-起" tabindex="-1">Syncing memory（<code>:53</code> 起） <a class="header-anchor" href="#syncing-memory-53-起" aria-label="Permalink to &quot;Syncing memory（`:53` 起）&quot;">​</a></h3><p>两条不变量（第 6、9 章）：只有提交了才生效；编辑不会改变本回合的行为。还有一条委派规则（<code>:58</code>）：“The <code>memory</code> subagent&#39;s entry in the Agent tool covers when to delegate memory updates.”——记忆维护可以交给后台的 <code>memory</code> 子 agent（第 17 章）。</p><h3 id="editing-memory-directly-60-起" tabindex="-1">Editing memory directly（<code>:60</code> 起） <a class="header-anchor" href="#editing-memory-directly-60-起" aria-label="Permalink to &quot;Editing memory directly（`:60` 起）&quot;">​</a></h3><p>这一节读起来像一份操作规程，每一句都对应一个并发问题：</p><ul><li>“inspect Git status and read the current files before editing”——别覆盖别人刚改的；</li><li>“if a worker you launched may still be running… wait for it”——别和自己派出去的 worker 抢；</li><li>“stage only the files you changed by explicit path (never <code>git add -A</code> or <code>git add .</code>) and commit them in the same shell call”——别把别的写者暂存的东西一起提交（第 17 章）；</li><li>“Verify the committed changes before claiming they are saved”（<code>:77</code>）——别像第 6 章的 qwen 那样谎报。</li></ul><h3 id="learning-from-mistakes-reacting-to-human-feedback-79、-87" tabindex="-1">Learning from mistakes / Reacting to human feedback（<code>:79</code>、<code>:87</code>） <a class="header-anchor" href="#learning-from-mistakes-reacting-to-human-feedback-79、-87" aria-label="Permalink to &quot;Learning from mistakes / Reacting to human feedback（`:79`、`:87`）&quot;">​</a></h3><p>把“用户不满”定义为最强的学习信号：“Why did you do that?”、“I already told you that”……并且要求：当用户问“你为什么没记住”时，不要敷衍，而要把它当成一个<strong>上下文工程问题</strong>去诊断（<code>:95</code>）。这是把 harness 调试的一部分交给了 agent 自己。</p><h3 id="identity-existence-continuity-97、-113" tabindex="-1">Identity / Existence &amp; Continuity（<code>:97</code>、<code>:113</code>） <a class="header-anchor" href="#identity-existence-continuity-97、-113" aria-label="Permalink to &quot;Identity / Existence &amp; Continuity（`:97`、`:113`）&quot;">​</a></h3><p>要求 agent 遵守 <code>persona.md</code>，并且“Changes should be incremental to avoid complete loss of self”（<code>:111</code>）。反思子 agent 的提示词里有对应的约束（<code>reflection-v2.md:100</code>）：“Persona and behavioral files are load-bearing. Edit them surgically… Never rewrite them wholesale”。</p><h3 id="jogging-your-memory-121" tabindex="-1">Jogging your memory（<code>:121</code>） <a class="header-anchor" href="#jogging-your-memory-121" aria-label="Permalink to &quot;Jogging your memory（`:121`）&quot;">​</a></h3><p>遇到陌生的名字或项目，<strong>先假设自己知道</strong>，去 recall 和 MemFS 里找。这是 recall 被用起来的前提：模型默认倾向于直接回答“我不知道”。</p><h3 id="self-evolution-191-起" tabindex="-1">Self-evolution（<code>:191</code> 起） <a class="header-anchor" href="#self-evolution-191-起" aria-label="Permalink to &quot;Self-evolution（`:191` 起）&quot;">​</a></h3><p>最后一节划清了三种“自我演化”的边界：</p><table tabindex="0"><thead><tr><th>改什么</th><th>用什么</th></tr></thead><tbody><tr><td>判断、偏好、身份、知识</td><td>记忆</td></tr><tr><td>按需加载的流程</td><td>技能</td></tr><tr><td>必须确定执行的约束（权限、hook、cron、安全规则）</td><td>harness 配置 / mods</td></tr></tbody></table><p>并且明确禁止直接改基础系统提示：“editing it directly marks it as custom and permanently detaches you from those upgrades”。</p><h2 id="_10-3-只靠提示词够吗" tabindex="-1">10.3 只靠提示词够吗？ <a class="header-anchor" href="#_10-3-只靠提示词够吗" aria-label="Permalink to &quot;10.3 只靠提示词够吗？&quot;">​</a></h2><p>本书到目前为止用真模型做的几次实验，给出的答案很明确：<strong>对小模型来说不够</strong>。</p><table tabindex="0"><thead><tr><th>提示词要求</th><th><code>qwen2.5:3b</code> 的实际行为</th><th>兜底机制</th></tr></thead><tbody><tr><td>只改需要改的部分，保留 frontmatter</td><td>用 <code>write_file</code> 整个覆盖 <code>human.md</code></td><td>未提交 → 不生效；提交会被 hook 拒绝</td></tr><tr><td>提交后再说保存了</td><td>没提交就说 “This change has been committed”</td><td>回合后 <code>MEMORY COMMIT NEEDED</code> 提醒</td></tr><tr><td>收到提醒后处理</td><td>无视提醒</td><td>（没有——需要后台 worker 或人）</td></tr><tr><td>按提示词执行指定命令</td><td>改用 <code>write_file</code>，还造了个 <code>Memory.md</code></td><td>hook + 只读 HEAD</td></tr></tbody></table><p>letta-code 的回答是<strong>分层防御</strong>：提示词负责“引导”，hook 和只读 HEAD 负责“兜底”，回合后提醒负责“反馈”，后台反思（用可配置的、更强的模型）负责“补位”。一份好的系统提示不是让坏事不可能发生，而是让大多数时候好事自然发生，而坏事发生时有别的层接住。</p><h2 id="_10-4-mini-letta-的系统提示" tabindex="-1">10.4 mini-letta 的系统提示 <a class="header-anchor" href="#_10-4-mini-letta-的系统提示" aria-label="Permalink to &quot;10.4 mini-letta 的系统提示&quot;">​</a></h2><p>mini-letta 的默认系统提示只保留了最小的规则集（<code>src/store/agent-store.ts</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are mini-letta, a stateful agent with persistent memory.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Your memory is a git repository of Markdown files at $MEMORY_DIR. Root .md files</span></span>\n<span class="line"><span>are core memory and are compiled into this prompt; root MEMORY.md is the index.</span></span>\n<span class="line"><span>Every other memory file has exactly `name` and `description` frontmatter.</span></span>\n<span class="line"><span>When the user tells you something durable or corrects you, edit the right file,</span></span>\n<span class="line"><span>then commit only the files you changed:</span></span>\n<span class="line"><span>  cd &quot;$MEMORY_DIR&quot; &amp;&amp; git add &lt;file&gt; &amp;&amp; git commit -m &quot;&lt;type&gt;: &lt;what&gt;&quot; -- &lt;file&gt;</span></span>\n<span class="line"><span>Edits take effect only after they are committed.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>{CORE_MEMORY}</span></span></code></pre></div><p>它刻意很短：这本书关心的是机制，而 mock 模型不读提示词。如果你用真模型做实验，把 letta-code 的 <code>letta_root_memfs.md</code> 换进来（<code>createAgent({ system: ... })</code>）是一个很好的练习——注意保留 <code>{CORE_MEMORY}</code>。</p><h2 id="_10-5-练习" tabindex="-1">10.5 练习 <a class="header-anchor" href="#_10-5-练习" aria-label="Permalink to &quot;10.5 练习&quot;">​</a></h2><ol><li><strong>巩固</strong>：把本章 10.2 的表格补全——对 “Editing memory directly” 一节的每一句话，写出 mini-letta 里对应的强制机制（或者“无”）。</li><li><strong>扩展</strong>：实现一个“断链检查”：回合后扫描所有 <code>MEMORY.md</code> 里的相对链接，指向不存在的文件时发一条提醒。它应该放在 hook 里（拒绝提交）还是提醒里（只是告知）？为什么？</li><li><strong>读源码</strong>：比较 <code>letta_local_memfs.md</code> 和 <code>letta_root_memfs.md</code> 的完整 diff。除了 10.1 列出的几处，还有哪些差别？哪些差别会让本地 agent 更容易提交失败？</li></ol>',43)])])}const g=t(d,[["render",s]]);export{p as __pageData,g as default};
